// Keep article depth identical after every language switch.
for (const lang of languages.map((language) => language.code)) {
  copy[lang].articles = completedArticles(lang);
}

export function localizedPath(lang: Lang, path = "") {
  const clean = path.replace(/^\/+|\/+$/g, "");
  const prefix = lang === "en" ? "" : `/${lang}`;
  return `${prefix}/${clean}${clean ? "/" : ""}`.replace(/\/+/g, "/");
}
